// For messages without encryption, we don't want to warn
// when there is an invalid signature, because that shouldn't be
// shown as being worse as a plain message without any signature.
// However, if the message contains encryption, we want to avoid
// that the user falsely concludes that encrypted means completely
// safe and secure. That's why we still remind the user about
// bad signatures in encrypted messages.
if (
  signedState &&
  (encryptedState || !["notok", "mismatch", "unknown"].includes(signedState))
) {
  if (signedState === "notok") {
    // Show the same as mismatch.
    signedState = "mismatch";
  }
  signedIcon.hidden = false;
  signedIcon.setAttribute(
    "src",
    `chrome://messenger/skin/icons/message-signed-${signedState}.svg`
  );
  // Set alt text.
  document.l10n.setAttributes(
    signedIcon,
    `openpgp-message-header-signed-${signedState}-icon`
  );
} else {
  signedIcon.hidden = true;
  signedIcon.removeAttribute("data-l10n-id");
  signedIcon.removeAttribute("alt");
  signedIcon.removeAttribute("src");
}

Assert.ok(!getMsgBodyTxt(msgc).includes(MSG_TEXT), "message text is in body");
// Note this is an S/MIME signature status, at the time of writing
// this test, string "mismatch" is used for status "notok".
Assert.ok(
  OpenPGPTestUtils.hasNoSignedIconState(aboutMessage.document),
  "signed icon should NOT be shown for status mismatch"
);
Assert.ok(
  !OpenPGPTestUtils.hasEncryptedIconState(aboutMessage.document, "ok"),
  "encrypted icon should NOT be shown"
);
await BrowserTestUtils.closeWindow(msgc);
